with filtered as (select *, case when country = 'US' then 1 else 0 end as is_us, coalesce(country, 'NONE') as country_clean from sessions where browser in ('Safari', 'Edge')), with_gaps as (select *, case when started_at - lag(started_at) over (partition by browser order by started_at, id) > interval 90 days then 1 else 0 end as is_new_session from filtered), sessions_sessions as (select *, sum(is_new_session) over (partition by browser order by started_at, id rows between unbounded preceding and current row) as session_no from with_gaps) select date_trunc('year', started_at) as year_start, round(sum(session_no) / nullif(count(case when browser = 'Chrome' then 1 end), 0), 2) as session_no_per_chrome, max(is_new_session) filter (where browser = 'Chrome') as chrome_max_is_new_session, percentile_approx(is_new_session, array(0.25, 0.5, 0.75)) as is_new_session_quartiles, max(is_us) as max_is_us from sessions_sessions group by date_trunc('year', started_at) having max(is_new_session) filter (where browser = 'Chrome') < 0 order by year_start desc;
